```javascript
/**
 * @param {number} n
 * @yields {number}
 */
function* factorial(n) {
    // Generator that yields factorial numbers from 1! to n!.
    // For n = 0, only yields 1 (0!).
    if (n === 0) {
        yield 1;
        return;
    }
    let product = 1;
    for (let i = 1; i <= n; i++) {
        product *= i;
        yield product;
    }
}
